```ts
abstract class Handler {
  protected next?: Handler;
  setNext(h: Handler): Handler { this.next = h; return h; }
  handle(req: Request): Response {
    return this.next ? this.next.handle(req) : this.defaultResponse();
  }
  protected defaultResponse(): Response { return { status: 200 }; }
}

class AuthHandler extends Handler {
  handle(req: Request) {
    if (!req.token) return { status: 401 };
    return super.handle(req);
  }
}
class RateLimitHandler extends Handler {
  handle(req: Request) {
    if (isOverLimit(req.clientIp)) return { status: 429 };
    return super.handle(req);
  }
}

const auth = new AuthHandler();
const rateLimit = new RateLimitHandler();
auth.setNext(rateLimit);
auth.handle(incomingRequest);   // runs auth, then rate-limit, then default
```

`AuthHandler` never imports or knows about `RateLimitHandler` directly by type — it only calls `super.handle()`, which forwards to whatever was wired in as `next`.
